# Generated by manage.py generate_test_cases.
"""Scoped calendar rendering through the actual Inbox component endpoint."""

from datetime import timedelta

from django.http import HttpResponse

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestInboxCalendarComponent(InboxCalendarFixtures, BloomerpComponentTestCase):
    view_name = "components_inbox_calendar"

    def extendedSetup(self) -> None:
        """Create selected shared Inbox references and independently placed meetings."""
        self.prepare_calendar()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover placement isolation, mixed dates, paging, revoked access, and read-only requests."""
        kwargs = {"inbox_id": self.source.pk}
        return [
            RequestScenario(
                name="Mode changes retain the canonical calendar page in browser history",
                user=self.actor,
                view_kwargs=kwargs,
                headers={
                    "HX-Target": "data-view-data-section",
                    "X-Bloomerp-Inbox-Calendar-Mode": "true",
                },
                query_params={"calendar_view_mode": "month"},
                expected=ExpectedResult(
                    response_validators=self.header_equals(
                        "HX-Push-Url",
                        f"/inbox/{self.source.pk}/calendar/?calendar_view_mode=month",
                    )
                ),
            ),
            RequestScenario(
                name="Anonymous calendar requests require login",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Other user cannot access the Inbox",
                user=self.outsider,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Inbox ownership alone does not grant event access",
                user=self.owner,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Shared reference uses source placements and standard calendar",
                user=self.actor,
                view_kwargs={"inbox_id": self.reference.pk},
                expected=ExpectedResult(response_validators=self.shared_calendar),
            ),
            RequestScenario(
                name="Only placements in this Inbox are shown",
                user=self.actor,
                view_kwargs=kwargs,
                expected=ExpectedResult(
                    response_validators=[
                        self.does_not_contain_text(self.unplaced.title),
                        self.does_not_contain_text(self.cancelled.title),
                    ]
                ),
            ),
            RequestScenario(
                name="Week month day year and list modes remain available",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"calendar_view_mode": "month"},
                expected=ExpectedResult(
                    response_validators=self.contains_text('data-view-mode="month"')
                ),
            ),
            RequestScenario(
                name="All-day range includes its second date",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={
                    "calendar_view_mode": "list",
                    "calendar_unit": (self.today + timedelta(days=1)).isoformat(),
                    "calendar_unit_offset": "0",
                },
                expected=ExpectedResult(
                    response_validators=self.contains_text(self.all_day.title)
                ),
            ),
            RequestScenario(
                name="Exclusive all-day end does not create an extra day",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={
                    "calendar_view_mode": "list",
                    "calendar_unit": (self.today + timedelta(days=2)).isoformat(),
                    "calendar_unit_offset": "0",
                },
                expected=ExpectedResult(
                    response_validators=self.does_not_contain_text(self.all_day.title)
                ),
            ),
            RequestScenario(
                name="Load-more URLs stay under the scoped Inbox route",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"calendar_view_mode": "day"},
                prepare=self.prepare_many,
                expected=ExpectedResult(response_validators=self.scoped_load_more),
            ),
            RequestScenario(
                name="Paging returns only remaining records in this Inbox",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={
                    "calendar_view_mode": "day",
                    "calendar_unit": self.today.isoformat() + "T10",
                    "calendar_unit_offset": "5",
                },
                prepare=self.prepare_many,
                expected=ExpectedResult(response_validators=self.remaining_records),
            ),
            RequestScenario(
                name="Search cannot bypass Inbox placement",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"q": self.unplaced.title},
                expected=ExpectedResult(
                    response_validators=self.does_not_contain_text(
                        f'data-object-id="{self.unplaced.pk}"'
                    )
                ),
            ),
            RequestScenario(
                name="Forged organizer filter cannot expand placements",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"inboxes": str(self.other_inbox.pk)},
                expected=ExpectedResult(
                    response_validators=self.does_not_contain_text(self.unplaced.title)
                ),
            ),
            RequestScenario(
                name="Revoked shared reference is denied on refresh",
                user=self.actor,
                view_kwargs={"inbox_id": self.reference.pk},
                prepare=self.revoke_share,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Date mutation cannot use this component",
                user=self.actor,
                method="POST",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=405),
            ),
            RequestScenario(
                name="Invalid page is rejected",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"calendar_page": "9999999999"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Overnight meetings stay timed on both dates",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"calendar_view_mode": "week"},
                prepare=self.prepare_overnight,
                expected=ExpectedResult(response_validators=self.overnight_segments),
            ),
        ]

    def shared_calendar(self, response: HttpResponse) -> bool:
        """Check mixed event display, read-only flags, and a single placed timed event."""
        body = response.content.decode()
        return (
            'bloomerp-component="calendar"' in body
            and self.timed.title in body
            and self.all_day.title in body
            and body.count(f'data-object-id="{self.timed.pk}"') == 1
            and 'draggable="true"' not in body
            and "data-calendar-unscheduled-event" not in body
        )

    def prepare_many(self, scenario: RequestScenario) -> None:
        """Place enough meetings in the same hour to exercise standard unit paging."""
        for index in range(6):
            event = self.create_event(f"Additional meeting {index}")
            event.inboxes.add(self.source)

    def scoped_load_more(self, response: HttpResponse) -> bool:
        """Ensure the standard load-more control targets the scoped calendar endpoint."""
        body = response.content.decode()
        return (
            "data-calendar-load-more" in body
            and f"/inbox/{self.source.pk}/calendar/" in body
            and "calendar_unit_offset=5" in body
        )

    def remaining_records(self, response: HttpResponse) -> bool:
        """Confirm the second unit page renders two records rather than other Inbox events."""
        return response.content.decode().count("data-calendar-event\n") == 2

    def revoke_share(self, scenario: RequestScenario) -> None:
        """Remove source access while leaving the stale reference selected."""
        self.source.shared_with_users.remove(self.actor)

    def prepare_overnight(self, scenario: RequestScenario) -> None:
        """Create a timed meeting crossing midnight within this calendar week."""
        # Use the beginning of the displayed week so both dates remain in view.
        monday = self.start - timedelta(days=self.start.weekday())
        start = monday.replace(hour=23)
        self.overnight = self.create_event(
            "Overnight timed meeting", start=start, end=start + timedelta(hours=2)
        )
        self.overnight.inboxes.add(self.source)

    def overnight_segments(self, response: HttpResponse) -> bool:
        """Confirm overnight events render as two timed segments with the same meeting ID."""
        return (
            response.content.decode().count(f'data-object-id="{self.overnight.pk}"')
            == 2
        )
